  h <- push(h, 5)
  h <- push(h, 3)
  h <- push(h, 8)
  h <- push(h, 1)
  h <- push(h, 9)
  h <- push(h, 2)

  print(peek(h))    
  print(h)

  res <- pop(h)
  print(res$value)  
  print(res$heap) 
}

