pub fn sort(A: []i32) void {
    var n = A.len;
    while (n > 1) {
        var new_n: usize = 0;
        for (A[0 .. n - 1], 0..) |value, i| {
            if (value > A[i + 1]) {
                mem.swap(i32, &A[i], &A[i + 1]);
                new_n = i + 1;
            }
        }
        n = new_n;
    }
