fn _binary_search<T: Ord>(arr: &[T], target: &T) -> usize {
    let mut low = 0;
    let mut high = arr.len();

    while low < high {
        let mid = low + (high - low) / 2;

        if arr[mid] < *target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    low
}

pub fn binary_insertion_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();

    for i in 1..len {
        let key = arr[i].clone();
        let index = _binary_search(&arr[..i], &key);

        arr[index..=i].rotate_right(1);
        arr[index] = key;
    }
}

